import heapq
class Solution:
    def shortestPathWithHops(self, n, edges, s, d, k):
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w)); g[v].append((u, w))
        INF = float('inf')
        dist = [[INF] * (k + 1) for _ in range(n)]
        dist[s][0] = 0
        pq = [(0, s, 0)]
        while pq:
            dd, u, h = heapq.heappop(pq)
            if dd > dist[u][h]: continue
            if u == d: return dd
            for v, w in g[u]:
                if dd + w < dist[v][h]:
                    dist[v][h] = dd + w
                    heapq.heappush(pq, (dd + w, v, h))
                if h < k and dd < dist[v][h + 1]:
                    dist[v][h + 1] = dd
                    heapq.heappush(pq, (dd, v, h + 1))
        return -1

