class Solution {
    public int shortestPathWithHops(int n, int[][] edges, int s, int d, int k) {
        List<List<long[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(new long[]{e[1], e[2]}); g.get(e[1]).add(new long[]{e[0], e[2]}); }
        long[][] dist = new long[n][k + 1];
        for (long[] r : dist) java.util.Arrays.fill(r, Long.MAX_VALUE);
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        dist[s][0] = 0; pq.add(new long[]{0, s, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll(); long dd = cur[0]; int u = (int) cur[1], h = (int) cur[2];
            if (dd > dist[u][h]) continue;
            if (u == d) return (int) dd;
            for (long[] nb : g.get(u)) {
                int v = (int) nb[0]; long w = nb[1];
                if (dd + w < dist[v][h]) { dist[v][h] = dd + w; pq.add(new long[]{dd + w, v, h}); }
                if (h < k && dd < dist[v][h + 1]) { dist[v][h + 1] = dd; pq.add(new long[]{dd, v, h + 1}); }
            }
        }
        return -1;
    }
}

