var shortestPathWithHops = function(n, edges, s, d, k) {
    const g = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { g[u].push([v, w]); g[v].push([u, w]); }
    const dist = Array.from({length: n}, () => Array(k + 1).fill(Infinity));
    dist[s][0] = 0;
    const pq = [[0, s, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [dd, u, h] = pq.shift();
        if (dd > dist[u][h]) continue;
        if (u === d) return dd;
        for (const [v, w] of g[u]) {
            if (dd + w < dist[v][h]) { dist[v][h] = dd + w; pq.push([dd + w, v, h]); }
            if (h < k && dd < dist[v][h + 1]) { dist[v][h + 1] = dd; pq.push([dd, v, h + 1]); }
        }
    }
    return -1;
};

