class Solution {
    public int shortestPathWithHops(int n, int[][] edges, int s, int d, int k) {
        long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[n]; java.util.Arrays.fill(dp, INF); dp[s] = 0;
        for (int r = 0; r <= k; r++) {
            long[] ndp = dp.clone();
            for (int[] e : edges) {
                int u = e[0], v = e[1]; long w = e[2];
                ndp[v] = Math.min(ndp[v], Math.min(dp[u] + w, dp[v]));
                ndp[u] = Math.min(ndp[u], Math.min(dp[v] + w, dp[u]));
            }
            dp = ndp;
        }
        return (int) dp[d];
    }
}

